    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           Handles navigation, animations, progress bar,
           nav dots, bar chart animations
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.totalSlides = this.slides.length;
                this.currentIndex = 0;
                this.isScrolling = false;

                this.progressBar = document.getElementById('progressBar');
                this.navDotsContainer = document.getElementById('navDots');

                this.setupNavDots();
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.setupScrollObserver();
            }

            /* Generate navigation dots */
            setupNavDots() {
                this.slides.forEach((_, i) => {
                    const dot = document.createElement('button');
                    dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                    dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
                    dot.addEventListener('click', () => this.goToSlide(i));
                    this.navDotsContainer.appendChild(dot);
                });
                this.dots = this.navDotsContainer.querySelectorAll('.nav-dot');
            }

            /* Intersection observer triggers .visible on slides + animates bars */
            setupIntersectionObserver() {
                const options = { threshold: 0.5 };
                this.observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            this.animateBars(entry.target);
                            // Update current index and UI
                            const idx = Array.from(this.slides).indexOf(entry.target);
                            if (idx !== -1) this.updateUI(idx);
                        }
                    });
                }, options);
                this.slides.forEach(slide => this.observer.observe(slide));
            }

            /* Animate bar charts when slides become visible */
            animateBars(slide) {
                const fills = slide.querySelectorAll('.bar-fill, .monthly-fill');
                fills.forEach(fill => {
                    const pct = fill.dataset.pct;
                    if (pct) {
                        setTimeout(() => {
                            fill.style.width = pct + '%';
                        }, 150);
                    }
                });
            }

            /* Update progress bar and active dot */
            updateUI(idx) {
                this.currentIndex = idx;
                // Progress bar
                const progress = ((idx + 1) / this.totalSlides) * 100;
                this.progressBar.style.width = progress + '%';
                // Nav dots
                this.dots.forEach((dot, i) => {
                    dot.classList.toggle('active', i === idx);
                    // White slides: use dark dots
                    const slide = this.slides[i];
                    const isDark = slide.classList.contains('slide-title') ||
                                   slide.classList.contains('slide-saas') ||
                                   slide.classList.contains('slide-monthly') ||
                                   slide.classList.contains('slide-market');
                    dot.classList.toggle('dark-dot', !isDark);
                });
            }

            /* Smooth scroll to slide */
            goToSlide(idx) {
                if (idx < 0 || idx >= this.totalSlides) return;
                this.slides[idx].scrollIntoView({ behavior: 'smooth' });
            }

            /* Keyboard navigation */
            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    switch(e.key) {
                        case 'ArrowDown':
                        case 'ArrowRight':
                        case ' ':
                            e.preventDefault();
                            this.goToSlide(this.currentIndex + 1);
                            break;
                        case 'ArrowUp':
                        case 'ArrowLeft':
                            e.preventDefault();
                            this.goToSlide(this.currentIndex - 1);
                            break;
                        case 'Home':
                            e.preventDefault();
                            this.goToSlide(0);
                            break;
                        case 'End':
                            e.preventDefault();
                            this.goToSlide(this.totalSlides - 1);
                            break;
                    }
                });
            }

            /* Touch/swipe navigation */
            setupTouchNav() {
                let startY = 0;
                let startX = 0;
                document.addEventListener('touchstart', (e) => {
                    startY = e.touches[0].clientY;
                    startX = e.touches[0].clientX;
                }, { passive: true });
                document.addEventListener('touchend', (e) => {
                    const dy = startY - e.changedTouches[0].clientY;
                    const dx = startX - e.changedTouches[0].clientX;
                    if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 50) {
                        this.goToSlide(this.currentIndex + (dy > 0 ? 1 : -1));
                    }
                }, { passive: true });
            }

            /* Scroll observer to track current slide for progress/dots */
            setupScrollObserver() {
                // Handled via IntersectionObserver above
            }
        }

        // Boot the presentation
        const presentation = new SlidePresentation();

        // Trigger first slide animations on load
        window.addEventListener('load', () => {
            const firstSlide = document.querySelector('.slide');
            if (firstSlide) {
                setTimeout(() => {
                    firstSlide.classList.add('visible');
                    presentation.animateBars(firstSlide);
                    presentation.updateUI(0);
                }, 100);
            }
        });
    </script>
